                                    <circle cx="0" cy="0" r="50" fill="#cbd5e1" /> <!-- Earth -->
                                    <circle cx="0" cy="0" r="150" class="orbit-path" /> <!-- Moon Orbit -->
                                    <circle cx="150" cy="0" r="10" fill="#94a3b8" /> <!-- Moon -->
                                    <ellipse cx="0" cy="0" rx="350" ry="350" class="orbit-path" /> <!-- Asteria Orbit -->
