    <!-- Detail Drawer -->
    <div class="overlay" id="drawer-overlay"></div>
    <div class="drawer" id="detail-drawer">
        <div class="drawer-header">
            <h2 id="drawer-title">Probe Details</h2>
            <button class="icon-btn" id="close-drawer">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
        </div>
        <div class="drawer-body">
            <div class="flex gap-4 mb-4">
                <div class="card flex-1">
                    <div class="text-xs text-muted">STATUS</div>
                    <div class="font-bold" id="drawer-status">NOMINAL</div>
                </div>
                <div class="card flex-1">
                    <div class="text-xs text-muted">UPTIME</div>
                    <div class="font-bold" id="drawer-uptime">142d 12h</div>
                </div>
            </div>
            <h3 class="text-sm font-bold mb-2">Telemetry History</h3>
            <div class="card" style="height: 150px; display:flex; align-items:center; justify-content:center; background: var(--bg-surface);">
                <span class="text-muted text-xs">[Detailed Graph Placeholder]</span>
            </div>
            <h3 class="text-sm font-bold mt-4 mb-2">Recent Logs</h3>
            <ul class="text-sm text-muted list-disc pl-4" id="drawer-logs">
                <li>System check passed</li>
                <li>Telemetry packet received</li>
            </ul>
        </div>
        <div class="drawer-footer">
            <button class="icon-btn" style="flex:1; border:1px solid var(--border-color);" onclick="showToast('Ping sent', 'info')">Ping Probe</button>
            <button class="icon-btn" style="flex:1; border:1px solid var(--accent-danger); color:var(--accent-danger);" onclick="confirmAction('Reboot', 'Are you sure you want to reboot this probe?')">Reboot</button>
        </div>
