    <!-- Command Palette -->
    <div class="overlay" id="cmd-overlay"></div>
    <div class="command-palette" id="cmd-palette">
        <input type="text" class="cmd-input" placeholder="Type a command or search..." id="cmd-input">
        <div class="cmd-list" id="cmd-list">
            <!-- Populated by JS -->
        </div>
    </div>

    <!-- Toast Container -->
    <div class="toast-container" id="toast-container"></div>

    <script>
        /* --- DATA & STATE --- */
        const state = {
            theme: localStorage.getItem('theme') || 'dark',
            sidebarCollapsed: localStorage.getItem('sidebar') === 'collapsed',
            fleet: [
                { id: 'N-01', name: 'Vanguard Alpha', status: 'Nominal', dist: 0.45, sig: -42, temp: 280, pwr: 98, last: '10s ago' },
                { id: 'N-02', name: 'Vanguard Beta', status: 'Nominal', dist: 0.45, sig: -45, temp: 275, pwr: 96, last: '12s ago' },
                { id: 'N-03', name: 'Scout I', status: 'Degraded', dist: 1.2, sig: -85, temp: 310, pwr: 45, last: '2m ago' },
                { id: 'N-04', name: 'Scout II', status: 'Nominal', dist: 1.2, sig: -82, temp: 290, pwr: 88, last: '15s ago' },
                { id: 'N-05', name: 'Orbiter A', status: 'Critical', dist: 3.5, sig: -110, temp: 400, pwr: 12, last: '1h ago' },
                { id: 'N-06', name: 'Orbiter B', status: 'Nominal', dist: 3.5, sig: -105, temp: 295, pwr: 92, last: '5s ago' },
                { id: 'N-07', name: 'Lander 1', status: 'Offline', dist: 3.5, sig: 0, temp: 0, pwr: 0, last: '4d ago' },
                { id: 'N-08', name: 'Relay Sat', status: 'Nominal', dist: 0.003, sig: -20, temp: 300, pwr: 100, last: '1s ago' }
            ],
            events: [
                { id: 1, type: 'critical', msg: 'Orbiter A thermal runaway detected', time: '10:42:05' },
                { id: 2, type: 'warning', msg: 'Scout I signal degradation', time: '10:30:12' },
                { id: 3, type: 'info', msg: 'Vanguard Alpha orbit insertion complete', time: '09:15:00' },
                { id: 4, type: 'info', msg: 'Daily telemetry dump received', time: '08:00:00' },
                { id: 5, type: 'warning', msg: 'Relay Sat battery fluctuation', time: '07:45:22' },
                { id: 6, type: 'critical', msg: 'Lander 1 comms lost', time: 'Yesterday' }
            ],
            telemetry: {
                signal: [],
                thermal: [],
                power: []
            },
            orbitScale: 1
        };

        // Initialize Telemetry Data
        for(let i=0; i<50; i++) {
            state.telemetry.signal.push(80 + Math.random() * 10);
            state.telemetry.thermal.push(280 + Math.random() * 20);
            state.telemetry.power.push(90 + Math.random() * 5);
        }

        /* --- DOM ELEMENTS --- */
        const els = {
            body: document.body,
            sidebar: document.getElementById('sidebar'),
            themeToggle: document.getElementById('theme-toggle'),
            utcClock: document.getElementById('utc-clock'),
            fleetTbody: document.getElementById('fleet-tbody'),
            fleetSearch: document.getElementById('fleet-search'),
            statusFilter: document.getElementById('status-filter'),
            emptyState: document.getElementById('empty-state'),
            eventList: document.getElementById('event-list'),
            eventFilter: document.getElementById('event-filter'),
            drawer: document.getElementById('detail-drawer'),
            drawerOverlay: document.getElementById('drawer-overlay'),
            closeDrawer: document.getElementById('close-drawer'),
            cmdPalette: document.getElementById('cmd-palette'),
            cmdOverlay: document.getElementById('cmd-overlay'),
            cmdInput: document.getElementById('cmd-input'),
            cmdList: document.getElementById('cmd-list'),
            toastContainer: document.getElementById('toast-container'),
            svgSignal: document.getElementById('line-signal'),
            svgThermal: document.getElementById('line-thermal'),
            svgPower: document.getElementById('line-power'),
            orbitGroup: document.getElementById('orbit-group'),
            probesLayer: document.getElementById('probes-layer')
        };

        /* --- INITIALIZATION --- */
        function init() {
            applyTheme(state.theme);
            if(state.sidebarCollapsed) els.sidebar.classList.add('collapsed');

            // Skeleton Loading Simulation
            setTimeout(() => {
                document.querySelectorAll('.skeleton').forEach(el => el.style.display = 'none');
                renderFleet();
                renderEvents();
                renderTelemetry();
                renderOrbit();
                renderSparklines();
            }, 600);

            // Clock
            setInterval(() => {
                const now = new Date();
                els.utcClock.textContent = now.toISOString().split('T')[1].split('.')[0] + ' UTC';
            }, 1000);

            // Event Listeners
            setupEventListeners();
        }

        /* --- RENDERING FUNCTIONS --- */
        function renderFleet() {
            const term = els.fleetSearch.value.toLowerCase();
            const status = els.statusFilter.value;

            const filtered = state.fleet.filter(p => {
                const matchText = p.name.toLowerCase().includes(term) || p.id.toLowerCase().includes(term);
                const matchStatus = status === 'all' || p.status === status;
                return matchText && matchStatus;
            });

            els.fleetTbody.innerHTML = '';
            if(filtered.length === 0) {
                els.emptyState.style.display = 'flex';
            } else {
                els.emptyState.style.display = 'none';
                filtered.forEach(p => {
                    const tr = document.createElement('tr');
                    tr.innerHTML = `
                        <td><div class="font-bold">${p.id}</div><div class="text-xs text-muted">${p.name}</div></td>
                        <td><span class="status-badge status-${p.status.toLowerCase()}">${p.status}</span></td>
                        <td class="text-mono">${p.dist}</td>
                        <td class="text-mono ${p.sig < -100 ? 'text-danger' : ''}">${p.sig}</td>
                        <td class="text-mono ${p.temp > 350 ? 'text-warning' : ''}">${p.temp}</td>
                        <td class="text-mono">${p.pwr}%</td>
                        <td class="text-xs text-muted">${p.last}</td>
                    `;
                    tr.onclick = () => openDrawer(p);
                    els.fleetTbody.appendChild(tr);
                });
            }
        }

        function renderEvents() {
            const filter = els.eventFilter.value;
            els.eventList.innerHTML = '';
            state.events.forEach(e => {
                if(filter !== 'all' && e.type !== filter) return;
                const div = document.createElement('div');
                div.className = `event-item ${e.type}`;
                div.innerHTML = `
                    <span class="text-xs font-bold text-muted">${e.time}</span>
                    <span>${e.msg}</span>
                `;
                els.eventList.appendChild(div);
            });
        }

        function renderTelemetry() {
            const w = 600, h = 200;
            const data = state.telemetry;

            // Helper to generate path
            const getPath = (arr, min, max) => {
                return arr.map((val, i) => {
                    const x = (i / (arr.length - 1)) * w;
                    const y = h - ((val - min) / (max - min)) * h;
                    return `${i===0?'M':'L'} ${x} ${y}`;
                }).join(' ');
            };

            els.svgSignal.setAttribute('d', getPath(data.signal, 70, 100));
            els.svgThermal.setAttribute('d', getPath(data.thermal, 250, 450));
            els.svgPower.setAttribute('d', getPath(data.power, 0, 100));
        }

        function renderOrbit() {
            els.orbitGroup.setAttribute('transform', `scale(${state.orbitScale})`);

            // Render probes on orbit
            els.probesLayer.innerHTML = '';
            state.fleet.forEach((p, i) => {
                if(p.status === 'Offline') return;
                const angle = (Date.now() / 5000) + (i * 1.5); // Simple animation
                const r = p.dist * 100; // Scale distance for visual
                const x = Math.cos(angle) * r;
                const y = Math.sin(angle) * r;

                const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                circle.setAttribute("cx", x);
                circle.setAttribute("cy", y);
                circle.setAttribute("r", 3);
                circle.setAttribute("fill", p.status === 'Critical' ? 'var(--accent-danger)' : 'var(--accent-primary)');
                els.probesLayer.appendChild(circle);
            });

            if(document.visibilityState === 'visible') requestAnimationFrame(renderOrbit);
        }

        function renderSparklines() {
            // Simple sparkline generation for KPIs
            const ids = ['spark-1', 'spark-2', 'spark-3', 'spark-4'];
            ids.forEach(id => {
                const svg = document.getElementById(id);
                let d = 'M0 10';
                for(let i=1; i<=10; i++) {
                    d += ` L${i*10} ${Math.random()*20}`;
                }
                const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
                path.setAttribute("d", d);
                path.setAttribute("fill", "none");
                path.setAttribute("stroke", "currentColor");
                path.setAttribute("stroke-width", "2");
                path.setAttribute("opacity", "0.5");
                svg.appendChild(path);
            });
        }

        /* --- INTERACTION LOGIC --- */
        function setupEventListeners() {
            // Theme
            els.themeToggle.onclick = () => {
                state.theme = state.theme === 'dark' ? 'light' : 'dark';
                localStorage.setItem('theme', state.theme);
                applyTheme(state.theme);
            };

            // Sidebar Toggle (Mobile)
            document.getElementById('mobile-menu-btn').onclick = () => {
                els.sidebar.classList.toggle('mobile-open');
            };

            // Sidebar Collapse (Desktop)
            // Add a small toggle button to sidebar bottom or hover logic? 
            // For simplicity, let's use a double click on logo or just keep it simple.
            // Let's add a click handler to the logo area for desktop collapse
            document.querySelector('.logo-area').addEventListener('dblclick', (e) => {
                if(window.innerWidth > 1024) {
                    state.sidebarCollapsed = !state.sidebarCollapsed;
                    localStorage.setItem('sidebar', state.sidebarCollapsed ? 'collapsed' : 'expanded');
                    els.sidebar.classList.toggle('collapsed');
                }
            });

            // Fleet Filters
            els.fleetSearch.addEventListener('input', renderFleet);
            els.statusFilter.addEventListener('change', renderFleet);
            els.eventFilter.addEventListener('change', renderEvents);

            // Drawer
            els.closeDrawer.onclick = closeDrawer;
            els.drawerOverlay.onclick = closeDrawer;

            // Command Palette
            document.addEventListener('keydown', (e) => {
                if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
                    e.preventDefault();
                    openCommandPalette();
                }
                if (e.key === 'Escape') {
                    closeCommandPalette();
                    closeDrawer();
                }
            });
            els.cmdInput.addEventListener('input', filterCommands);

            // Orbit Controls
            document.getElementById('zoom-in').onclick = () => { state.orbitScale += 0.2; };
            document.getElementById('zoom-out').onclick = () => { state.orbitScale = Math.max(0.2, state.orbitScale - 0.2); };
            document.getElementById('zoom-reset').onclick = () => { state.orbitScale = 1; };

            // Simulate Update
            document.getElementById('btn-simulate').onclick = simulateTelemetry;

            // Kanban Drag & Drop
            const board = document.getElementById('kanban-board');
            const cards = document.querySelectorAll('.kanban-card');

            cards.forEach(card => {
                card.addEventListener('dragstart', () => card.classList.add('dragging'));
                card.addEventListener('dragend', () => card.classList.remove('dragging'));
            });

            board.addEventListener('dragover', e => {
                e.preventDefault();
                const afterElement = getDragAfterElement(board, e.clientY);
                const draggable = document.querySelector('.dragging');
                if (afterElement == null) {
                    board.appendChild(draggable);
                } else {
                    board.insertBefore(draggable, afterElement);
                }
            });
        }

        function applyTheme(theme) {
            document.documentElement.setAttribute('data-theme', theme);
        }

        function openDrawer(probe) {
            document.getElementById('drawer-title').textContent = probe.name;
            document.getElementById('drawer-status').textContent = probe.status.toUpperCase();
            document.getElementById('drawer-status').className = `font-bold status-${probe.status.toLowerCase()}`;
            els.drawer.classList.add('open');
            els.drawerOverlay.classList.add('active');
        }

        function closeDrawer() {
            els.drawer.classList.remove('open');
            els.drawerOverlay.classList.remove('active');
        }

        function openCommandPalette() {
            els.cmdPalette.classList.add('active');
            els.cmdOverlay.classList.add('active');
            els.cmdInput.value = '';
            els.cmdInput.focus();
            filterCommands();
        }

        function closeCommandPalette() {
            els.cmdPalette.classList.remove('active');
            els.cmdOverlay.classList.remove('active');
        }

        function filterCommands() {
            const val = els.cmdInput.value.toLowerCase();
            const items = [
                { label: 'Overview', action: () => showToast('Navigating to Overview', 'info') },
                { label: 'Fleet Status', action: () => showToast('Opening Fleet View', 'info') },
                { label: 'Telemetry Logs', action: () => showToast('Downloading Logs...', 'info') },
                { label: 'Toggle Theme', action: () => els.themeToggle.click() },
                { label: 'Simulate Alert', action: () => showToast('CRITICAL: Oxygen Leak Detected', 'danger') }
            ];

            const filtered = items.filter(i => i.label.toLowerCase().includes(val));
            els.cmdList.innerHTML = filtered.map((item, idx) => `
                <div class="cmd-item ${idx===0?'selected':''}" onclick="executeCommand('${item.label}')">
                    <span>${item.label}</span>
                    <span class="cmd-shortcut">↵</span>
                </div>
            `).join('');
        }

        // Global function for onclick handlers in HTML strings
        window.executeCommand = (label) => {
            if(label === 'Toggle Theme') els.themeToggle.click();
            else if(label === 'Simulate Alert') showToast('CRITICAL: Oxygen Leak Detected', 'danger');
            else showToast(`Action: ${label}`, 'info');
            closeCommandPalette();
        };

        window.resetFilters = () => {
            els.fleetSearch.value = '';
            els.statusFilter.value = 'all';
            renderFleet();
        };

        window.sortTable = (key) => {
            // Simple sort toggle
            state.fleet.sort((a, b) => {
                if(key === 'id') return a.id.localeCompare(b.id);
                if(key === 'dist') return a.dist - b.dist;
                if(key === 'sig') return a.sig - b.sig;
                if(key === 'temp') return a.temp - b.temp;
                if(key === 'pwr') return a.pwr - b.pwr;
                return 0;
            });
            renderFleet();
        };

        function simulateTelemetry() {
            // Shift arrays
            state.telemetry.signal.shift();
            state.telemetry.signal.push(80 + Math.random() * 10);
            state.telemetry.thermal.shift();
            state.telemetry.thermal.push(280 + Math.random() * 20);
            state.telemetry.power.shift();
            state.telemetry.power.push(90 + Math.random() * 5);

            renderTelemetry();
            showToast('Telemetry updated', 'success');

            // Update KPI numbers slightly
            document.getElementById('kpi-latency').textContent = Math.floor(140 + Math.random() * 10);
        }

        function getDragAfterElement(container, y) {
            const draggableElements = [...container.querySelectorAll('.kanban-card:not(.dragging)')];
            return draggableElements.reduce((closest, child) => {
                const box = child.getBoundingClientRect();
                const offset = y - box.top - box.height / 2;
                if (offset < 0 && offset > closest.offset) {
                    return { offset: offset, element: child };
                } else {
                    return closest;
                }
            }, { offset: Number.NEGATIVE_INFINITY }).element;
        }

        /* --- TOAST & MODAL SYSTEM --- */
        window.showToast = (msg, type = 'info') => {
            const toast = document.createElement('div');
            toast.className = 'toast';
            const color = type === 'danger' ? 'var(--accent-danger)' : (type === 'success' ? 'var(--accent-success)' : 'var(--accent-primary)');
            toast.innerHTML = `
                <div style="width:8px;height:8px;border-radius:50%;background:${color}"></div>
                <span>${msg}</span>
            `;
            els.toastContainer.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                setTimeout(() => toast.remove(), 300);
            }, 3000);
        };

        window.confirmAction = (title, msg) => {
            // Simple custom modal implementation
            const overlay = document.createElement('div');
            overlay.className = 'overlay active';
            overlay.style.zIndex = '2000';
            const modal = document.createElement('div');
            modal.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:var(--bg-panel);border:1px solid var(--border-color);padding:2rem;border-radius:8px;width:300px;z-index:2001;box-shadow:0 10px 25px rgba(0,0,0,0.5);';
            modal.innerHTML = `
                <h3 style="margin-bottom:1rem">${title}</h3>
                <p style="margin-bottom:1.5rem;color:var(--text-secondary)">${msg}</p>
                <div style="display:flex;justify-content:flex-end;gap:0.5rem">
                    <button id="modal-cancel" class="icon-btn" style="border:1px solid var(--border-color)">Cancel</button>
                    <button id="modal-confirm" class="icon-btn" style="background:var(--accent-danger);color:white">Confirm</button>
                </div>
            `;
            document.body.appendChild(overlay);
            document.body.appendChild(modal);

            document.getElementById('modal-cancel').onclick = () => { overlay.remove(); modal.remove(); };
            document.getElementById('modal-confirm').onclick = () => { 
                showToast('Action confirmed', 'success'); 
                overlay.remove(); modal.remove(); 
            };
        };

        // Start
        init();

    </script>
</body>
